"""Data models for AstroPratidin Multi-Agent Pipeline."""
from dataclasses import dataclass, field
from datetime import date
from typing import Dict, List, Optional


@dataclass
class AstroBrief:
    """Strategic editorial brief generated by the Strategist Agent."""
    publication_date: str
    main_theme: str
    macro_hook: str
    key_planetary_aspects: List[str]
    high_impact_rashis: List[str]
    suggested_titles: List[str]
    suggested_tags: List[str]


@dataclass
class ScriptDraft:
    """Draft produced by the Creator Agent."""
    title: str
    description: str
    tags: List[str]
    hook: str
    intro: str
    rashi_sections: Dict[str, str]
    outro: str
    full_script_md: str
    revision: int = 0
    feedback_incorporated: str = ""


@dataclass
class ReviewVerdict:
    """Evaluation verdict produced by the Reviewer Agent."""
    approved: bool
    overall_score: float  # Scale 1 - 10
    astrological_fidelity_score: float  # 1 - 10
    viewer_hook_score: float  # 1 - 10
    emotional_resonance_score: float  # 1 - 10
    policy_compliance_score: float  # 1 - 10
    feedback: str
    revision_count: int = 0


@dataclass
class AgentPipelineState:
    """Shared state dictionary across the agent graph."""
    date: date
    planetary_positions: List[Dict[str, any]]
    transit_events: List[Dict[str, any]]
    brief: Optional[AstroBrief] = None
    draft: Optional[ScriptDraft] = None
    review: Optional[ReviewVerdict] = None
    max_revisions: int = 2
